'use strict';
const blankCandidate=()=>({name:'',email:'',universe:'',discipline:'',projectTitle:'',projectUrl:'',website:'',socialType:'Instagram',socialUrl:'',interests:[],audienceChannel:'',audience:'',visual:'',attachment:'',publicConsent:false,privacyConsent:false,charter:false});
const initialState=()=>({lang:'fr',candidate:blankCandidate(),application:'draft',published:null,member:false,demoSession:false,tab:'home',filter:'all',search:'',works:[],opportunities:[],messages:[],shareDrafts:{},next:1});
let state=initialState();
const t=(fr,en)=>state.lang==='fr'?fr:en;
const tr=x=>typeof x==='object'&&x!==null?(x[state.lang]||x.fr||''):x;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=x=>{try{return ['http:','https:'].includes(new URL(x).protocol)}catch{return false}};
const labels={discipline:{image:['Image & illustration','Image & illustration'],words:['Écriture','Writing'],sound:['Musique & son','Music & sound'],film:['Film & animation','Film & animation'],interactive:['Jeu & interactif','Games & interactive'],other:['Autre pratique','Another practice']},interest:{imaginary:['Mondes imaginaires','Imaginary worlds'],urban:['Ville & quotidien','Cities & everyday life'],nature:['Nature & vivant','Nature & living things'],sound:['Son & mouvement','Sound & movement']}};
const label=(group,key)=>labels[group][key]?t(...labels[group][key]):key;
function publicCopy(c){return {id:'alex',name:c.name,discipline:c.discipline,tagline:c.universe,bio:c.universe,project:'own',site:c.website,social:c.socialType,socialUrl:c.socialUrl,interests:[...c.interests],avatar:2,color:'#edb399',visual:c.visual,projectTitle:c.projectTitle,projectUrl:c.projectUrl,open:true};}
const Model={
 validateCandidate(c){const errors=[];if(!c.name.trim())errors.push('name');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.email))errors.push('email');if(c.universe.trim().length<20)errors.push('universe');if(!c.discipline)errors.push('discipline');if(!c.projectTitle.trim())errors.push('projectTitle');if(!c.interests.length)errors.push('interests');if(!c.audienceChannel||!c.audience)errors.push('audience');for(const k of ['projectUrl','website','socialUrl'])if(c[k]&&!safeUrl(c[k]))errors.push(k);if(!c.privacyConsent)errors.push('privacyConsent');if(!c.charter)errors.push('charter');return errors;},
 submit(){if(this.validateCandidate(state.candidate).length)return false;if(state.application==='pending')return false;state.application='pending';if(!state.candidate.publicConsent)state.published=null;return true;},
 moderate(decision){if(state.application!=='pending')return false;if(decision==='approve'){state.application='accepted';state.member=true;state.demoSession=false;state.published=state.candidate.publicConsent?publicCopy(state.candidate):null;}else state.application='changes';return true;},
 demo(){state.demoSession=true;state.tab='home';},
 queueWork(work){if(!(state.member||state.demoSession)||!work.title.trim()||!safeUrl(work.url)||!work.context.trim()||!work.consent)return false;state.works.push({...work,id:'submitted-'+state.next++,status:'pending'});return true;},
 moderateWork(id,decision){const w=state.works.find(x=>x.id===id);if(!w||w.status!=='pending')return false;w.status=decision==='approve'?'selected':'changes';return true;},
 request(person,kind,text,format,timing){if(!(state.member||state.demoSession)||text.trim().length<20)return false;if(state.messages.some(m=>m.person===person&&m.kind===kind&&m.status==='pending'))return false;state.messages.push({id:state.next++,person,kind,text,format,timing,status:'pending'});return true;},
 respond(id,status){const m=state.messages.find(x=>x.id===Number(id));if(!m||m.status!=='pending'||!['accepted','declined','cancelled'].includes(status))return false;m.status=status;return true;},
 withdraw(){state.published=null;state.candidate.publicConsent=false;},
 reset(){state=initialState();}
};
function creators(){return [...DEMO_DATA.creators,...(state.published?[state.published]:[])];}
function creator(id){return creators().find(c=>c.id===id)||DEMO_DATA.creators[0];}
function works(){return [...DEMO_DATA.works,...state.works.filter(w=>w.status==='selected').map(w=>({id:w.id,creator:'alex',art:2,title:w.title,category:t('Proposition de membre','Member submission'),description:w.context,need:w.need,url:w.url,round:true,submitted:true}))];}
function roundWorks(){return [...works().filter(w=>w.submitted).reverse(),...DEMO_DATA.works.filter(w=>w.round)].slice(0,3);}
function avatar(c){return `<span class="avatar">${c.visual?`<img alt="${esc(t('Visuel de','Visual for'))} ${esc(c.name)}" src="${esc(c.visual)}">`:portrait(c.avatar||0,c.color||'#edb399')}</span>`;}
function badge(text){return `<span class="tag">${esc(text)}</span>`;}
function title(eyebrow,heading,copy=''){return `<div class="page-head"><span class="eyebrow">${eyebrow}</span><h1>${heading}</h1>${copy?`<p>${copy}</p>`:''}</div>`;}
function workCard(w){const c=w.creator==='alex'?(state.published||publicCopy(state.candidate.name?state.candidate:{...demoCandidate(),publicConsent:false})):creator(w.creator);return `<article class="work"><div class="work-art">${artwork(w.art)}${badge(tr(w.category))}</div><div class="work-body"><a class="work-by" href="#/creator/${c.id}">${avatar(c)}<span>${esc(c.name)}</span></a><h3>${esc(tr(w.title))}</h3><p>${esc(tr(w.description))}</p><p class="micro">${esc(tr(w.need))}</p><div class="work-foot"><a href="#/work/${w.id}" class="link">${t('Découvrir l’œuvre','Explore the work')} ↗</a><button class="plain" data-action="share" data-id="${w.id}">${t('Recommander','Recommend')}</button></div></div></article>`;}
function creatorCard(c){return `<a class="creator-card" href="#/creator/${c.id}">${avatar(c)}<h3>${esc(c.name)}</h3><p>${esc(label('discipline',c.discipline))}</p><div class="tags">${c.interests.slice(0,2).map(i=>badge(label('interest',i))).join('')}</div><span class="go">↗</span></a>`;}
function opportunityCard(o){const c=creator(o.creator);return `<article class="opportunity"><span class="eyebrow">${esc(c.name)} · ${t('APPEL À CO-CRÉATION','OPEN COLLABORATION')}</span><h3>${esc(tr(o.title))}</h3><p>${esc(tr(o.description))}</p><div class="meta"><span>${esc(tr(o.format))}</span><span>${esc(tr(o.effort))}</span></div><div class="actions" style="margin-top:22px"><button class="button small" data-action="opportunity" data-id="${o.id}">${t('Voir la proposition','Explore the idea')} ↗</button></div></article>`;}
function home(){return `<section class="hero"><div><span class="eyebrow">${t('CRÉATEURS INDÉPENDANTS. PAS SI SOLITAIRES.','INDEPENDENT CREATORS. NOT ALONE.')}</span><h1>${t('DES UNIVERS<br>QUI SE<br><em>CROISENT.</em>','GOOD WORK.<br>NEW<br><em>CONNECTIONS.</em>')}</h1><p>${t('Découvrez les créations des autres, faites circuler vos coups de cœur, et trouvez avec qui créer la suite.','Discover each other’s work, pass on what moves you, and find people to make something with.')}</p><div class="actions"><a href="#/round" class="button">${t('Explorer la ronde','Explore the round')} ↗</a><a href="#/join" class="link">${t('Rejoindre la meute','Join the pack')}</a></div></div><div class="hero-art" aria-label="${t('Collage de créations fictives','Collage of fictional works')}"><span class="sticker">${t('CHACUN SON MONDE.<br>PLUSIEURS CHEMINS.','DIFFERENT WORLDS.<br>SHARED POSSIBILITIES.')}</span><div class="art-card one">${artwork(0)}</div><div class="art-card two">${artwork(1)}</div><div class="dog" id="hero-dog">${DOG_SVG}</div></div></section><div class="ticker"><span>${t('Découvrir','Discover')}</span><b>✳</b><span>${t('Faire circuler','Pass it on')}</span><b>✳</b><span>${t('Créer ensemble','Create together')}</span><b>✳</b><span>${t('Rester soi-même','Stay yourself')}</span></div><section class="section"><div class="section-head"><div><span class="eyebrow">${t('LA RONDE · ÉDITION DE DÉMONSTRATION','THE ROUND · DEMO EDITION')}</span><h2>${t('À découvrir<br>en ce moment.','Worth your<br>attention right now.')}</h2></div><p>${t('Trois univers, choisis ensemble. Une petite sélection pour prendre le temps de regarder, écouter ou lire.','Three different worlds, brought together. A small selection worth taking time to see, hear or read.')}</p><a href="#/round" class="link">${t('Toute la ronde','The full round')} ↗</a></div><div class="grid-3">${roundWorks().map(workCard).join('')}</div><div class="round-note"><p>${t('Une œuvre vous parle ? Faites un retour à son auteur, recommandez-la avec vos mots ou imaginez une petite création à deux.','Something speaks to you? Tell its creator, recommend it in your own words, or imagine a small collaboration.')}</p><a href="#/studio" class="button light small">${t('Proposer mon œuvre','Submit my work')} ↗</a></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">${t('LE PORTFOLIO DE LA MEUTE','THE PACK’S PORTFOLIO')}</span><h2>${t('Derrière chaque création,<br>un monde à rencontrer.','Behind every piece,<br>a world to meet.')}</h2></div><a href="#/portfolio" class="link">${t('Tous les créateurs','All creators')} ↗</a></div><div class="grid-4">${creators().slice(0,4).map(creatorCard).join('')}</div></section><section class="section"><div class="section-head"><div><span class="eyebrow">${t('DES IDÉES QUI CHERCHENT UNE AUTRE MAIN','IDEAS LOOKING FOR ANOTHER PAIR OF HANDS')}</span><h2>${t('Et si on faisait ça<br>ensemble ?','What if we made<br>this together?')}</h2></div><a href="#/collaborations" class="link">${t('Les propositions','Open projects')} ↗</a></div><div class="opportunities">${DEMO_DATA.opportunities.map(opportunityCard).join('')}</div></section><section class="section"><div class="band"><div><h2>${t('Votre univers a sa place ici.','Your world belongs here.')}</h2><p>${t('Quelques lignes, votre projet et ce que vous avez envie d’explorer. Votre fiche n’apparaît qu’après votre accord et notre validation.','A few lines, your project and what you would like to explore. Your profile goes live only with your permission and after review.')}</p></div><a href="#/join" class="button lime">${t('Rejoindre la meute','Join the pack')} ↗</a></div></section>`;}
function portfolio(){const list=creators().filter(c=>(state.filter==='all'||c.discipline===state.filter)&&(`${c.name} ${tr(c.bio)} ${tr(c.tagline)}`.toLowerCase().includes(state.search.toLowerCase())));return title(t('PORTFOLIO PUBLIC','PUBLIC PORTFOLIO'),t('DES GENS.<br><em>DES MONDES.</em>','REAL CURIOSITY.<br><em>DIFFERENT WORLDS.</em>'),t('Entrez par une image, une pratique ou une curiosité. Pas besoin d’un compte pour découvrir.','Start with an image, a practice or a little curiosity. No account needed to explore.'))+`<div class="filters">${[['all',t('Tout voir','All work')],...Object.keys(labels.discipline).map(k=>[k,label('discipline',k)])].map(([k,v])=>`<button data-action="filter" data-filter="${k}" class="${state.filter===k?'selected':''}">${esc(v)}</button>`).join('')}<label class="search"><span class="visually-hidden">${t('Rechercher','Search')}</span><input id="creator-search" placeholder="${t('Un nom, un univers…','A name, a world…')}" value="${esc(state.search)}"></label></div><div id="portfolio-grid" class="grid-4">${list.length?list.map(creatorCard).join(''):`<div class="empty"><h3>${t('Aucun univers trouvé.','No matching worlds.')}</h3><button class="plain" data-action="clear-filter">${t('Réinitialiser les filtres','Reset filters')}</button></div>`}</div>`;}
function publicProfile(c,preview=false){const w=works().find(w=>w.id===c.project);return `${preview?`<div class="preview-label"><strong>${t('APERÇU PUBLIC','PUBLIC PREVIEW')}</strong><span>${t('Seuls ces éléments seront visibles. Email, audience et pièce jointe restent privés.','Only these details will be visible. Your email, audience details and attachment stay private.')}</span></div>`:''}<section class="profile"><aside class="profile-side">${avatar(c)}<h1>${esc(c.name)}</h1><p>${esc(label('discipline',c.discipline))}</p><div class="tags">${c.interests.map(i=>badge(label('interest',i))).join('')}</div><div class="links">${c.site?`<button data-action="external" data-url="${esc(c.site)}">${t('Site web','Website')} ↗</button>`:''}${c.socialUrl?`<button data-action="external" data-url="${esc(c.socialUrl)}">${esc(c.social)} ↗</button>`:''}</div></aside><div class="profile-content"><span class="eyebrow">${t('SON MONDE, EN QUELQUES MOTS','THEIR WORLD, IN A FEW WORDS')}</span><h2>${esc(tr(c.tagline))}</h2>${typeof c.bio==='object'?`<p class="lead">${esc(tr(c.bio))}</p>`:''}<div class="work-art">${artwork(w?w.art:2)}</div><div class="project"><span class="eyebrow">${t('LE PROJET DU MOMENT','THE CURRENT PROJECT')}</span><h3>${esc(w?tr(w.title):c.projectTitle)}</h3>${w?`<p>${esc(tr(w.description))}</p>`:''}<div class="actions">${w?`<a class="button" href="#/work/${w.id}">${t('Découvrir ce projet','Explore this project')} ↗</a>`:c.projectUrl?`<button class="button" data-action="external" data-url="${esc(c.projectUrl)}">${t('Voir le projet','View the project')} ↗</button>`:''}${!preview?`<button class="button light" data-action="message" data-person="${c.id}" data-kind="collaboration">${t('Proposer une collaboration','Suggest a collaboration')}</button>`:''}</div></div>${!preview?`<p class="micro">${t('Le collectif présente les univers. Chacun choisit ses échanges, ses collaborations et ses recommandations.','The collective introduces people’s worlds. Everyone chooses their own conversations, collaborations and recommendations.')}</p><button class="plain micro" data-action="report" data-person="${c.id}">${t('Signaler cette fiche','Report this profile')}</button>`:''}</div></section>`;}
function round(){return title(t('LA RONDE · SÉLECTION ÉDITORIALE','THE ROUND · AN EDITORIAL SELECTION'),t('TROIS PORTES.<br><em>À VOUS D’ENTRER.</em>','THREE OPEN DOORS.<br><em>COME ON IN.</em>'),t('Cette édition réunit une ville dessinée, un paysage sonore et une fiction sous la pluie. La sélection change ; les œuvres restent à découvrir.','This edition brings together a drawn city, a soundscape and a story in the rain. The selection changes; the work remains worth discovering.'))+`<div class="grid-3">${roundWorks().map(workCard).join('')}</div><div class="round-note"><p>${t('Prochaine ronde de démonstration : « Petits mondes » · propositions jusqu’au 29 octobre. Sélection éditoriale tournante, pas de classement par audience.','Next demo round: “Small worlds” · submissions through 29 October. A rotating editorial selection, not an audience ranking.')}</p><button class="button light small" data-action="open-submit-work">${t('Proposer mon œuvre','Submit my work')} ↗</button></div><section class="section"><div class="section-head"><div><span class="eyebrow">${t('LES ÉDITIONS PRÉCÉDENTES · FICTIVES','PREVIOUS EDITIONS · FICTIONAL')}</span><h2>${t('Les découvertes<br>ne disparaissent pas.','Good discoveries<br>do not disappear.')}</h2></div></div><div class="archive"><button data-action="archive" data-id="0"><strong>${t('Édition 01<br>Une fenêtre ouverte','Edition 01<br>An open window')}</strong><span>${t('Image, son et mouvement · ouvrir la sélection','Image, sound and movement · open the selection')} ↗</span></button><button data-action="archive" data-id="1"><strong>${t('Édition 02<br>Histoires de passage','Edition 02<br>Passing stories')}</strong><span>${t('Des récits courts, des idées qui voyagent · ouvrir','Short stories, ideas that travel · open')} ↗</span></button></div></section>`;}
function workPage(w){const c=w.creator==='alex'?(state.published||publicCopy(demoCandidate())):creator(w.creator);return `${title(tr(w.category),esc(tr(w.title)))}<div class="form-layout"><section><div class="work-art" style="height:370px;border:1px solid var(--ink);border-radius:8px">${artwork(w.art)}</div><div class="panel" style="margin-top:22px"><a class="work-by" href="#/creator/${c.id}">${avatar(c)}<span>${esc(c.name)} ↗</span></a><p>${esc(tr(w.description))}</p><p><strong>${t('L’auteur aimerait :','The creator would welcome:')}</strong> ${esc(tr(w.need))}.</p><button class="button" data-action="external" data-url="${esc(w.url)}">${t('Ouvrir l’œuvre originale','Open the original work')} ↗</button></div></section><aside><div class="aside-note"><span class="eyebrow">${t('UNE CRÉATION VOUS PARLE ?','SOMETHING SPEAKS TO YOU?')}</span><h2>${t('Donnez-lui<br>une suite.','Let it start<br>something.')}</h2><p>${t('Un retour précis, une recommandation sincère, une idée commune. Ou simplement le plaisir de découvrir.','A thoughtful response, a genuine recommendation, a shared idea. Or simply the pleasure of discovering it.')}</p><div class="actions"><button class="button" data-action="message" data-person="${c.id}" data-kind="feedback" data-work="${w.id}">${t('Faire un retour','Give feedback')}</button><button class="button light" data-action="share" data-id="${w.id}">${t('Partager avec mes mots','Share in my own words')}</button><button class="plain" data-action="message" data-person="${c.id}" data-kind="collaboration" data-work="${w.id}">${t('Imaginer une petite collaboration','Imagine a small collaboration')} ↗</button></div></div><p class="micro">${t('Aucune action obligatoire. Aucun like ou partage automatique.','No required actions. No automated likes or shares.')}</p></aside></div>`;}
function collaborations(){return title(t('CO-CONSTRUIRE','MAKE SOMETHING TOGETHER'),t('UNE IDÉE.<br><em>UNE AUTRE MAIN.</em>','ONE IDEA.<br><em>ANOTHER PAIR OF HANDS.</em>'),t('Un format, un premier pas, un cadre clair. Les bonnes collaborations peuvent commencer petit.','A format, a first step and clear expectations. Good collaborations can start small.'))+`<div class="opportunities">${DEMO_DATA.opportunities.map(opportunityCard).join('')}${state.opportunities.filter(o=>o.status==='published').map(o=>`<article class="opportunity"><span class="eyebrow">${t('PROPOSITION MEMBRE · DÉMO','MEMBER PROPOSAL · DEMO')}</span><h3>${esc(o.title)}</h3><p>${esc(o.description)}</p><div class="meta">${esc(o.format)} · ${esc(o.timing)}</div></article>`).join('')}</div><div class="round-note"><p>${t('Vous avez une idée précise en tête ? Proposez un format léger, le temps envisagé et les conditions de participation.','Have a specific idea? Suggest a small format, the time involved and clear terms for taking part.')}</p><button class="button light small" data-action="open-opportunity">${t('Proposer une co-création','Propose a collaboration')} ↗</button></div>`;}
function input(name,labelText,opts={}){return `<label>${labelText}<input name="${name}" data-candidate="${name}" type="${opts.type||'text'}" ${opts.required?'required':''} maxlength="${opts.max||160}" value="${esc(state.candidate[name])}" placeholder="${opts.placeholder||''}" autocomplete="off">${opts.note?`<span class="field-note">${opts.note}</span>`:''}</label>`;}
function selectField(name,labelText,options,required=true){return `<label>${labelText}<select name="${name}" data-candidate="${name}" ${required?'required':''}><option value="">${t('Choisir…','Choose…')}</option>${options.map(([v,l])=>`<option value="${v}" ${state.candidate[name]===v?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;}
function join(){const c=state.candidate;return title(t(state.member?'MA FICHE':'REJOINDRE LA MEUTE',state.member?'MY PROFILE':'JOIN THE PACK'),t('FAITES-NOUS<br><em>ENTRER DANS VOTRE MONDE.</em>','LET US INTO<br><em>YOUR WORLD.</em>'),t('Quelques informations utiles, pas un dossier de vingt pages. Vous verrez votre fiche avant toute publication.','A few useful details, not a twenty-page application. You will preview your profile before anything goes live.'))+`<div class="form-layout"><form id="application-form" novalidate><section class="panel"><div class="form-step"><strong>${t('01 · Votre fiche','01 · Your profile')}</strong><span>${t('PUBLIC APRÈS ACCORD ET VALIDATION','PUBLIC AFTER CONSENT AND REVIEW')}</span></div><div class="form-grid">${input('name',t('Nom de création / pseudo','Creative name / alias'),{required:true,max:60,placeholder:t('Votre nom ou celui de votre projet','Your name or your project’s name')})}${selectField('discipline',t('Votre pratique principale','Your main practice'),Object.entries(labels.discipline).map(([k,v])=>[k,t(...v)]))}</div><label>${t('Votre univers, en bref','Your world, in a nutshell')}<textarea name="universe" data-candidate="universe" required minlength="20" maxlength="300" rows="3" placeholder="${t('Ce que vous créez, ce qui vous anime…','What you make, what moves you…')}">${esc(c.universe)}</textarea><span class="field-note">${t('2–3 phrases · 300 caractères maximum','2–3 sentences · up to 300 characters')}</span></label><div class="form-grid">${input('projectTitle',t('Votre projet du moment','Your current project'),{required:true,max:100})}${input('projectUrl',t('Son lien, si disponible','Project link, if available'),{type:'url',placeholder:'https://'})}</div><fieldset><legend>${t('Vos centres d’intérêt · un ou plusieurs','Your interests · choose one or more')}</legend><div class="pill-checks">${Object.entries(labels.interest).map(([k,v])=>`<label><input type="checkbox" name="interest" value="${k}" ${c.interests.includes(k)?'checked':''}>${t(...v)}</label>`).join('')}</div></fieldset><details class="optional" ${c.website||c.socialUrl||c.visual?'open':''}><summary>${t('Ajouter mes liens et mon visuel · facultatif','Add my links and a visual · optional')}</summary><div class="form-grid">${input('website',t('Site / portfolio · facultatif','Website / portfolio · optional'),{type:'url',placeholder:'https://'})}${selectField('socialType',t('Un canal à présenter','A channel to feature'),['Instagram','YouTube','TikTok','Bandcamp','Vimeo','Newsletter','LinkedIn','Autre / Other'].map(k=>[k,k]),false)}</div>${input('socialUrl',t('Lien vers ce canal · facultatif','Link to this channel · optional'),{type:'url',placeholder:'https://',note:t('Seuls les liens que vous choisissez apparaîtront sur votre fiche.','Only the links you choose will appear on your profile.')})}<div class="upload-box"><div class="upload-row">${avatar({name:c.name||'Alex',avatar:2,color:'#edb399',visual:c.visual})}<div><label>${t('Photo ou visuel · facultatif','Photo or visual · optional')}<input type="file" id="visual-file" accept="image/png,image/jpeg,image/webp"></label><p class="micro">PNG, JPG, WebP · ${t('3 Mo max.','3 MB max.')} ${t('Aperçu local uniquement.','Local preview only.')}</p><button class="plain micro" type="button" data-action="demo-visual">${t('Utiliser le portrait de démonstration','Use the demo portrait')}</button>${c.visual?`<button class="plain micro" type="button" data-action="remove-visual">${t('Retirer','Remove')}</button>`:''}</div></div></div></details></section><section class="panel"><div class="form-step"><strong>${t('02 · Pour le collectif','02 · For the collective')}</strong><span>${t('PRIVÉ · JAMAIS SUR VOTRE FICHE','PRIVATE · NEVER ON YOUR PROFILE')}</span></div>${input('email',t('Email privé de suivi et de connexion','Private email for updates and sign-in'),{type:'email',required:true,placeholder:'alex@example.invalid'})}<div class="form-grid">${input('audienceChannel',t('Où rencontrez-vous votre public ?','Where do people follow your work?'),{required:true,max:100,placeholder:t('Instagram, newsletter, concerts…','Instagram, newsletter, live events…')})}${selectField('audience',t('Taille approximative de votre audience','Approximate audience size'),[['starting',t('Je débute / pas encore de public','Just starting / no audience yet')],['small','1–500'],['medium','500–2 000'],['growing','2 000–10 000'],['large','10 000+'],['unknown',t('Je ne sais pas','I don’t know')]])}</div><p class="micro">${t('Une indication pour comprendre vos canaux, pas un classement ni un minimum d’entrée. Pas besoin d’additionner des personnes présentes sur plusieurs réseaux.','This helps us understand your channels. It is not a ranking or an entry requirement. No need to add together people who follow you in more than one place.')}</p><label>${t('Une pièce utile pour présenter le projet · facultative','A useful project attachment · optional')}<input type="file" id="attachment-file" accept="application/pdf,image/png,image/jpeg,image/webp"><span class="field-note">PDF, PNG, JPG, WebP · ${t('10 Mo max.','10 MB max.')} ${t('Privée pour la candidature. Aucun fichier transmis dans cette démo.','Private application material. No file is uploaded in this demo.')}</span></label>${c.attachment?`<p class="upload-status">${esc(c.attachment)} <button type="button" class="plain" data-action="remove-attachment">${t('Retirer','Remove')}</button></p>`:''}<label class="check"><input type="checkbox" name="privacyConsent" data-candidate="privacyConsent" ${c.privacyConsent?'checked':''} required><span>${t('J’accepte que ces informations privées servent à examiner ma candidature et à gérer mon accès. Elles ne seront pas publiées.','I agree to these private details being used to review my application and manage my access. They will not be published.')}</span></label><label class="check"><input type="checkbox" name="charter" data-candidate="charter" ${c.charter?'checked':''} required><span>${t('Je respecte les créateurs et leurs droits. Aucun retour, like ou partage n’est obligatoire. Je suis autorisé·e à présenter les éléments fournis.','I respect creators and their rights. Feedback, likes and shares are never required. I have permission to present the material I provide.')}</span></label><div class="actions"><button class="button" type="submit">${t('Voir ma fiche avant envoi','Preview my profile')} ↗</button><button type="button" class="plain" data-action="fill-demo">${t('Remplir avec un exemple fictif','Fill with a fictional example')}</button></div><p class="micro">${t('Dans cette maquette, utilisez uniquement des données fictives. Rien n’est enregistré après fermeture ou rechargement.','Use fictional details only in this prototype. Nothing is kept after closing or reloading the page.')}</p></section></form><aside><div class="aside-note"><span class="eyebrow">${t('AVANT D’APPARAÎTRE','BEFORE YOU APPEAR')}</span><h2>${t('Vous choisissez<br>ce que l’on voit.','You choose<br>what people see.')}</h2><p>${t('Votre fiche raconte votre travail. Les détails de candidature restent entre vous et l’équipe.','Your profile tells the story of your work. Application details stay between you and the team.')}</p><div class="privacy-line"><strong>${t('Public','Public')}</strong><span>${t('Nom, univers, projet, intérêts, visuel et liens choisis.','Name, world, project, interests, visual and chosen links.')}</span></div><div class="privacy-line"><strong>${t('Privé','Private')}</strong><span>${t('Email, audience, pièce jointe et échanges.','Email, audience, attachment and conversations.')}</span></div></div><div class="aside-note soft"><h3>${t('Et ensuite ?','What happens next?')}</h3><ol><li>${t('Vous vérifiez l’aperçu.','You review the preview.')}</li><li>${t('Vous choisissez l’affichage public.','You choose public visibility.')}</li><li>${t('L’équipe examine la candidature.','The team reviews your application.')}</li><li>${t('Après accord, place à votre espace membre.','Once approved, your member space opens.')}</li></ol><p class="micro">${t('Aucun délai d’admission promis.','No admission time is promised.')}</p></div></aside></div>`;}
function preview(){if(Model.validateCandidate(state.candidate).length)return join();return publicProfile(publicCopy(state.candidate),true)+`<div class="preview-controls"><div><label class="check"><input id="public-consent" data-candidate="publicConsent" type="checkbox" ${state.candidate.publicConsent?'checked':''}><span><strong>${t('Je souhaite que cette fiche soit publique après validation.','I would like this profile to be public after approval.')}</strong><br>${t('Ce choix porte sur cette fiche et ses liens, pas sur une réutilisation de mes images sur les réseaux du collectif. Je peux retirer ma fiche.','This covers this profile and its links, not reuse of my images on the collective’s social channels. I can withdraw my profile.')}</span></label><p class="micro">${t('Vous pouvez candidater sans autoriser l’affichage public pour le moment.','You can apply without agreeing to a public profile yet.')}</p></div><div class="actions"><a href="#/join" class="button light">${t('Modifier','Edit')}</a><button class="button" data-action="submit-application" ${state.application==='pending'?'disabled':''}>${t('Soumettre · simulation','Submit · simulation')} ↗</button></div></div>`;}
function submitted(){const pending=state.application==='pending';return title(t('CANDIDATURE · SIMULATION','APPLICATION · SIMULATION'),pending?t('VOTRE MONDE<br><em>EST ENTRE NOS MAINS.</em>','YOUR WORLD.<br><em>READY FOR REVIEW.</em>'):t('VOTRE CANDIDATURE<br><em>A AVANCÉ.</em>','YOUR APPLICATION<br><em>HAS MOVED FORWARD.</em>'),t('La réception et l’examen sont simulés ici. Aucun message n’a été envoyé, aucune fiche publiée sur le vrai site.','Receipt and review are simulated here. No message has been sent and nothing has been published on the real site.'))+`<span class="status-chip">${statusLabel(state.application)}</span><div class="process"><div><span class="tiny">01</span><strong>${t('Candidature reçue','Application received')}</strong><p>${t('Vos éléments publics et privés sont séparés.','Public and private details are kept separate.')}</p></div><div><span class="tiny">02</span><strong>${t('Examen de la fiche','Profile review')}</strong><p>${t('Vérification des éléments, des liens et de votre accord d’affichage.','A review of the material, links and your publication choice.')}</p></div><div><span class="tiny">03</span><strong>${t('Accès et publication choisie','Access and chosen publication')}</strong><p>${t('L’espace s’ouvre après validation. La fiche reste privée sans votre accord.','Access opens after approval. Your profile stays private unless you consent.')}</p></div></div><div class="actions"><button class="button light" data-action="admin-receipt">${t('Voir la réception côté équipe · démo','See the team’s receipt · demo')}</button><a href="#/moderation" class="button">${t('Parcourir la validation · démo','Explore the review · demo')} ↗</a><a href="#/round" class="link">${t('Découvrir en attendant','Explore while you wait')}</a></div>`;}
function statusLabel(s){return ({draft:t('BROUILLON','DRAFT'),pending:t('À EXAMINER','PENDING REVIEW'),accepted:t('CANDIDATURE ACCEPTÉE · DÉMO','APPLICATION APPROVED · DEMO'),changes:t('AJUSTEMENT DEMANDÉ · DÉMO','CHANGES REQUESTED · DEMO'),selected:t('RETENUE POUR LA RONDE · DÉMO','SELECTED FOR THE ROUND · DEMO'),published:t('VISIBLE DANS LA DÉMO','VISIBLE IN THE DEMO'),private:t('FICHE NON PUBLIQUE','PROFILE NOT PUBLIC')})[s]||s;}
function demoCandidate(){return {name:'Alex Sillage',email:'alex@example.invalid',universe:t('Je crée des récits courts et des carnets illustrés autour des lieux que l’on traverse sans les regarder. J’aime croiser les mots et les images.','I make short stories and illustrated notebooks about places we pass without noticing. I like bringing words and images together.'),discipline:'words',projectTitle:t('Le carnet des passages','The passing places notebook'),projectUrl:'https://alex-sillage.example.invalid/carnet',website:'https://alex-sillage.example.invalid',socialType:'Newsletter',socialUrl:'https://newsletter.example.invalid/alex',interests:['urban','imaginary'],audienceChannel:'Newsletter + Instagram',audience:'small',visual:'',attachment:'portfolio-demo.pdf · '+t('nom fictif, aucun fichier','fictional name, no file'),publicConsent:false,privacyConsent:true,charter:true};}
function studio(){if(!(state.member||state.demoSession))return title(t('L’ATELIER DES MEMBRES','THE MEMBERS’ STUDIO'),t('CE QUI SE PASSE<br><em>ENTRE LES FICHES.</em>','WHAT HAPPENS<br><em>BETWEEN THE PROFILES.</em>'),t('Un espace pour faire évoluer sa fiche, proposer une œuvre, répondre à une idée ou lancer une petite co-création.','A space to update your profile, submit work, respond to an idea or start a small collaboration.'))+`<div class="studio-grid"><div class="stateless-card lime"><h2>${t('Explorer l’atelier','Explore the studio')}</h2><p>${t('Entrez avec Alex, un membre entièrement fictif. Pas de connexion réelle ni de données à fournir.','Step in as Alex, a completely fictional member. No real sign-in or personal details required.')}</p><button class="button" data-action="demo-login">${t('Entrer dans la démo membre','Enter the member demo')} ↗</button></div><div class="stateless-card"><h2>${t('Votre propre univers','Your own world')}</h2><p>${t('Le parcours complet commence par le formulaire, un aperçu de votre fiche et sa validation.','The full journey starts with an application form, your profile preview and a review.')}</p><a href="#/join" class="button light">${t('Remplir la candidature','Complete the application')}</a></div></div>`;
const tabs=[['home',t('Mon atelier','My studio')],['works',t('Mes propositions','My submissions')],['messages',t('Mes échanges','My conversations')],['profile',t('Ma fiche & mes choix','My profile & choices')]];
return `<div class="studio-top"><div><span class="eyebrow">${t('ESPACE MEMBRE · ACCÈS SIMULÉ','MEMBER SPACE · SIMULATED ACCESS')}</span><h1>${t('Bonjour','Hello')} ${esc((state.demoSession?'Alex':state.candidate.name).split(' ')[0])}.</h1><p>${t('Une œuvre à partager ? Une idée à faire grandir ?','Work to share? An idea to grow?')}</p></div><a href="#/round" class="button light">${t('Voir la ronde publique','View the public round')} ↗</a></div><nav class="studio-nav" aria-label="${t('Atelier','Studio')}">${tabs.map(([k,v])=>`<button data-action="tab" data-tab="${k}" class="${state.tab===k?'active':''}">${v}</button>`).join('')}</nav>${studioContent()}`;}
function studioContent(){
if(state.tab==='home')return `<div class="studio-grid"><section class="stateless-card lime"><span class="eyebrow">${t('VOTRE PROCHAINE OCCASION','YOUR NEXT OPPORTUNITY')}</span><h2>${t('La ronde « Petits mondes »','The “Small worlds” round')}</h2><p>${t('Une création, deux lignes de contexte et ce qui vous serait utile. Les propositions de cette démo sont ouvertes jusqu’au 29 octobre.','One piece, a few lines of context and what would be useful to you. This demo round accepts submissions through 29 October.')}</p><button class="button" data-action="open-submit-work">${t('Proposer mon œuvre','Submit my work')} ↗</button><p class="micro">${t('Sélection relue et tournante. Proposer ne garantit pas une mise en avant.','A reviewed, rotating selection. Submitting does not guarantee a feature.')}</p></section><section class="stateless-card"><span class="eyebrow">${t('FAIRE UN PAS VERS QUELQU’UN','MAKE A CONNECTION')}</span><h2>${t('Un projet à deux,<br>ça commence petit.','A project together<br>can start small.')}</h2><p>${t('Un format clair, un temps réaliste, les conditions annoncées. Pas besoin d’organiser un appel.','A clear format, realistic time and stated terms. No need to schedule a call.')}</p><button class="button light" data-action="open-opportunity">${t('Proposer une co-création','Propose a collaboration')} ↗</button></section></div><section class="section"><div class="section-head"><h2>${t('À lire, écouter,<br>regarder cette semaine.','Something to read,<br>hear or see this week.')}</h2><p>${t('Ce n’est pas une mission. Si une œuvre vous parle, choisissez votre manière de soutenir son auteur.','This is not an assignment. If a piece speaks to you, choose how you would like to support its creator.')}</p></div><div class="grid-3">${DEMO_DATA.works.slice(0,3).map(workCard).join('')}</div></section>`;
if(state.tab==='works')return `<div class="actions" style="margin-bottom:25px"><button class="button" data-action="open-submit-work">${t('Proposer une œuvre / actualité','Submit work / an update')}</button><button class="button light" data-action="open-opportunity">${t('Proposer une co-création','Propose a collaboration')}</button></div>${!state.works.length&&!state.opportunities.length?`<div class="empty"><h3>${t('La prochaine proposition peut être la vôtre.','The next submission could be yours.')}</h3><p>${t('Un lien suffit pour commencer.','One link is enough to start.')}</p></div>`:''}${state.works.map(w=>`<div class="list-row"><div class="mini-work"><div class="thumb">${artwork(2)}</div><div><h3>${esc(w.title)}</h3><p>${esc(w.need)}</p><span class="status-chip">${statusLabel(w.status)}</span></div></div><div class="actions">${w.status==='pending'?`<button class="plain" data-action="review-work" data-id="${w.id}">${t('Voir la validation · démo','Explore review · demo')}</button>`:w.status==='selected'?`<a href="#/round" class="link">${t('Voir dans la ronde','View in the round')} ↗</a>`:''}<button class="plain danger" data-action="withdraw-work" data-id="${w.id}">${t('Retirer','Withdraw')}</button></div></div>`).join('')}${state.opportunities.map(o=>`<div class="list-row"><div><h3>${esc(o.title)}</h3><p>${esc(o.format)} · ${esc(o.timing)}</p><span class="status-chip">${statusLabel(o.status)}</span></div><div class="actions">${o.status==='pending'?`<button class="plain" data-action="publish-opportunity" data-id="${o.id}">${t('Simuler la validation','Simulate approval')}</button>`:''}<button class="plain danger" data-action="withdraw-opportunity" data-id="${o.id}">${t('Retirer','Withdraw')}</button></div></div>`).join('')}`;
if(state.tab==='messages')return state.messages.length?state.messages.map(m=>{const c=creator(m.person);return `<article class="feedback"><span class="status-chip">${m.status==='pending'?t('EN ATTENTE · SIMULATION','PENDING · SIMULATION'):m.status==='accepted'?t('ACCORD MUTUEL · SIMULATION','MUTUAL AGREEMENT · SIMULATION'):m.status==='declined'?t('DÉCLINÉ · SIMULATION','DECLINED · SIMULATION'):t('ANNULÉ · SIMULATION','CANCELLED · SIMULATION')}</span><h3>${esc(c.name)} · ${m.kind==='feedback'?t('Un retour','Feedback'):t('Une idée commune','A shared idea')}</h3><p>${esc(m.text)}</p>${m.format?`<p class="micro">${esc(m.format)} · ${esc(m.timing)}</p>`:''}${m.status==='pending'?`<div class="actions"><button class="button small light" data-action="respond" data-id="${m.id}" data-status="accepted">${t('Simuler son accord','Simulate their acceptance')}</button><button class="plain" data-action="respond" data-id="${m.id}" data-status="declined">${t('Simuler son refus','Simulate a decline')}</button><button class="plain" data-action="respond" data-id="${m.id}" data-status="cancelled">${t('Annuler','Cancel')}</button></div>`:m.status==='accepted'?`<p class="micro">${t('L’échange pourrait maintenant continuer par email, après accord sur le partage des coordonnées. Aucun email ni adresse réelle n’a été transmis. Droits, crédit et conditions restent à convenir par écrit.','The conversation could now continue by email, with permission to share contact details. No email or real address has been sent. Rights, credit and terms still need to be agreed in writing.')}</p>`:''}</article>`;}).join(''):`<div class="empty"><h3>${t('Une conversation commence par une œuvre.','A conversation starts with a piece of work.')}</h3><p>${t('Découvrez une création puis laissez un retour ou proposez une petite collaboration.','Explore a piece, then leave feedback or suggest a small collaboration.')}</p><a href="#/round" class="button light">${t('Découvrir la ronde','Explore the round')} ↗</a></div>`;
return `<div class="studio-grid"><section class="stateless-card"><h2>${t('Votre fiche publique','Your public profile')}</h2><span class="status-chip">${state.published?statusLabel('published'):state.demoSession?t('PROFIL FICTIF ALEX','ALEX’S FICTIONAL PROFILE'):statusLabel('private')}</span><p style="margin-top:18px">${t('Votre email, votre audience et vos pièces de candidature n’y figurent jamais. Une modification publique repasse par la validation.','Your email, audience details and application files never appear here. Public changes go through review again.')}</p><div class="actions"><button class="button light" data-action="edit-profile">${t('Modifier ma fiche','Edit my profile')}</button>${state.published?`<a href="#/creator/alex" class="link">${t('Voir la fiche','View profile')} ↗</a><button class="plain danger" data-action="withdraw-profile">${t('Retirer du public','Remove from public view')}</button>`:''}</div></section><section class="stateless-card"><h2>${t('Un choix par usage','A choice for each use')}</h2><p>${t('Fiche publique, présence dans une ronde et reprise d’un visuel sur un réseau collectif sont trois choix différents. Aucun accord global caché.','A public profile, inclusion in a round and reuse of a visual on a collective social channel are three separate choices. No hidden blanket permission.')}</p><button class="plain" data-action="privacy">${t('Voir mes données et mes choix','View my details and choices')}</button><div class="divider"></div><button class="plain danger" data-action="leave">${t('Quitter et effacer cette démo','Leave and clear this demo')}</button></section></div>`;
}
function moderation(){const c=state.candidate;return title(t('VUE ÉQUIPE · SIMULATION','TEAM VIEW · SIMULATION'),t('UNE FICHE RELUE.<br><em>UN ACCORD RESPECTÉ.</em>','A REVIEWED PROFILE.<br><em>CONSENT RESPECTED.</em>'),t('Cette vue de démonstration n’est pas un véritable accès administrateur. Elle montre la validation avant l’apparition publique.','This demo view is not real administrator access. It shows the review that happens before a profile appears publicly.'))+`${c.name?`<div class="form-layout"><section class="panel"><span class="status-chip">${statusLabel(state.application)}</span><h2 style="margin-top:22px">${esc(c.name)}</h2><p>${esc(c.universe)}</p><p><strong>${esc(c.projectTitle)}</strong><br>${esc(c.projectUrl)}</p><div class="tags">${c.interests.map(i=>badge(label('interest',i))).join('')}</div><p><strong>${t('Accord d’affichage public :','Public profile consent:')}</strong> ${c.publicConsent?t('oui, après validation','yes, after review'):t('non — ne pas publier','no — do not publish')}</p><div class="actions"><a href="#/preview" class="button light">${t('Revoir l’aperçu public','Review the public preview')}</a>${state.application==='pending'?`<button class="button" data-action="moderate" data-decision="approve">${t(c.publicConsent?'Valider & publier dans la démo':'Accepter sans publier',c.publicConsent?'Approve & publish in the demo':'Approve without publishing')}</button><button class="plain" data-action="moderate" data-decision="changes">${t('Demander un ajustement','Request a change')}</button>`:state.application==='accepted'?`<a href="#/studio" class="button">${t('Ouvrir l’espace membre','Open the member space')} ↗</a>`:`<a href="#/join" class="button">${t('Ajuster la candidature','Update the application')}</a>`}</div></section><aside class="panel private-summary"><span class="eyebrow">${t('DONNÉES DE CANDIDATURE · PRIVÉES','APPLICATION DETAILS · PRIVATE')}</span><dl><dt>Email</dt><dd>${esc(c.email)}</dd><dt>${t('Canaux','Channels')}</dt><dd>${esc(c.audienceChannel)}</dd><dt>${t('Audience','Audience')}</dt><dd>${esc(c.audience)}</dd><dt>${t('Pièce jointe','Attachment')}</dt><dd>${esc(c.attachment||t('Aucune','None'))}</dd></dl><h3>${t('Notification à l’équipe','Team notification')}</h3><p>${t('Un email de réception serait envoyé avec un lien sécurisé vers cette revue. Pas de pièce privée en publication automatique.','A receipt email would link to this secure review. Private files are never automatically published.')}</p><button class="plain" data-action="admin-receipt">${t('Ouvrir l’email simulé','Open the simulated email')}</button></aside></div>`:`<div class="empty"><h3>${t('Pas de candidature à examiner.','No application to review.')}</h3><a href="#/join" class="button light">${t('Commencer la candidature','Start an application')}</a></div>`}`;}
let focusBeforeModal=null;
const $=s=>document.querySelector(s);
function notify(text){$('#status').innerHTML=text?`<div class="notice">${esc(text)}</div>`:'';}
function closeDialog(){if($('#dialog').open)$('#dialog').close();if(focusBeforeModal?.isConnected)focusBeforeModal.focus();}
function openDialog(html){focusBeforeModal=document.activeElement;$('#dialog-body').innerHTML=html;$('#dialog-label').textContent=t('DÉMONSTRATION PRIVÉE · AUCUN ENVOI','PRIVATE DEMO · NOTHING IS SENT');$('#dialog').showModal();}
function go(route){if(location.hash==='#/'+route)render();else location.hash='/'+route;}
function requireMember(){if(state.member||state.demoSession)return true;openDialog(`<h2 id="dialog-title">${t('Entrez dans l’atelier','Step into the studio')}</h2><p>${t('Les retours et propositions partent de l’espace membre. Vous pouvez l’explorer avec Alex, sans créer de vrai compte.','Feedback and proposals come from the member space. Explore it as Alex without creating a real account.')}</p><div class="actions"><button class="button" data-action="demo-login">${t('Explorer avec Alex · démo','Explore as Alex · demo')}</button><a href="#/join" class="button light">${t('Ma candidature','My application')}</a></div>`);return false;}
function render(){closeDialog();const parts=(location.hash.replace(/^#\/?/,'')||'home').split('/');const route=parts[0];document.documentElement.lang=state.lang;document.title='StrayDogs Collective · '+t('Maquette privée V2','Private prototype V2');$('#demo-bar').innerHTML=`<strong>${t('MAQUETTE PRIVÉE · V2','PRIVATE PROTOTYPE · V2')}</strong><span>${t('Créateurs et œuvres fictifs · aucune donnée transmise · recharger efface la démo','Fictional creators and work · no data sent · reloading clears the demo')}</span><button class="plain" data-action="reset">${t('Réinitialiser','Reset')}</button>`;$('#header').innerHTML=`<a href="#/home" class="brand"><small>CONFLUENCE OF MINDS</small><strong>STRAYDOGS <em>COLLECTIVE</em><span class="paw">✳</span></strong></a><nav class="nav" aria-label="${t('Navigation principale','Main navigation')}">${[['round',t('La ronde','The round')],['portfolio',t('Les créateurs','Creators')],['collaborations',t('Co-créer','Co-create')]].map(([r,l])=>`<a href="#/${r}" ${route===r?'aria-current="page"':''}>${l}</a>`).join('')}<a class="nav-studio" href="#/studio">${t('Espace membre','Member space')}</a><a class="nav-join" href="#/join">${t('Rejoindre','Join the pack')} ↗</a></nav><div class="lang"><button data-action="lang" data-lang="fr" class="${state.lang==='fr'?'active':''}" aria-label="Français">FR</button><span>/</span><button data-action="lang" data-lang="en" class="${state.lang==='en'?'active':''}" aria-label="English">EN</button></div>`;
let html;if(route==='home')html=home();else if(route==='portfolio')html=portfolio();else if(route==='round')html=round();else if(route==='collaborations')html=collaborations();else if(route==='join')html=join();else if(route==='preview')html=preview();else if(route==='submitted')html=submitted();else if(route==='moderation')html=moderation();else if(route==='studio')html=studio();else if(route==='creator'){const c=creators().find(c=>c.id===parts[1]);html=c?publicProfile(c):title(t('FICHE NON PUBLIQUE','PROFILE NOT PUBLIC'),t('CE MONDE N’EST PAS<br><em>ENCORE VISIBLE.</em>','THIS WORLD IS NOT<br><em>PUBLIC YET.</em>'),t('Une fiche n’apparaît qu’après accord et validation.','A profile only appears after consent and review.'))+`<a class="button light" href="#/portfolio">${t('Voir les créateurs','Browse creators')}</a>`;}else if(route==='work'){const w=works().find(w=>w.id===parts[1]);html=w?workPage(w):round();}else html=home();$('#main').innerHTML=html;
$('#footer').innerHTML=`<div><a class="brand" href="#/home"><small>CONFLUENCE OF MINDS</small><strong>STRAYDOGS COLLECTIVE ✳</strong></a><p>${t('Des créations qui se croisent. Des recommandations sincères. Des projets à plusieurs.','Work that connects. Genuine recommendations. Things made together.')}</p></div><div class="footer-links"><button class="plain" data-action="contact">${t('Une question ? Nous contacter','A question? Contact us')}</button><button class="plain" data-action="charter">${t('L’esprit du collectif','Our shared spirit')}</button><a href="#/moderation">${t('Vue équipe · démo','Team view · demo')}</a></div>`;
}
function openWorkForm(){if(!requireMember())return;openDialog(`<h2 id="dialog-title">${t('Votre œuvre dans<br>la prochaine ronde ?','Your work in<br>the next round?')}</h2><p>${t('Un lien, un peu de contexte et ce qui vous serait utile. L’équipe relit avant toute mise en avant.','One link, a little context and what would help. The team reviews it before any feature.')}</p><form id="work-form"><label>${t('Titre de l’œuvre ou de l’actualité','Work or update title')}<input name="title" required maxlength="100" placeholder="${t('Le carnet des passages','The passing places notebook')}"></label><label>${t('Lien original','Original link')}<input name="url" required type="url" placeholder="https://example.invalid/mon-projet"></label><label>${t('Pourquoi la découvrir ?','Why discover it?')}<textarea name="context" required maxlength="350" rows="3"></textarea></label><label>${t('Ce qui me serait utile','What I would welcome')}<select name="need"><option>${t('Un regard extérieur','A fresh perspective')}</option><option>${t('Un relais sincère, si cela vous parle','A genuine recommendation, if it speaks to you')}</option><option>${t('Un partenaire pour une petite collaboration','A partner for a small collaboration')}</option></select></label><label class="check"><input type="checkbox" name="consent" required><span>${t('Je suis autorisé·e à présenter cette œuvre et j’accepte sa mise en avant dans la ronde publique, si elle est retenue.','I have permission to present this work and agree to a public feature in the round if selected.')}</span></label><label class="check"><input type="checkbox" name="socialPermission"><span>${t('Facultatif : l’équipe peut me proposer une reprise de ce visuel sur ses réseaux. Le support et le crédit seront validés avec moi avant diffusion.','Optional: the team may ask me about using this visual on its channels. I will approve the channel and credit before it is shared.')}</span></label><button class="button">${t('Soumettre pour examen · simulation','Submit for review · simulation')}</button></form>`);}
function openOpportunityForm(){if(!requireMember())return;openDialog(`<h2 id="dialog-title">${t('Une idée à construire<br>avec quelqu’un.','An idea to build<br>with someone.')}</h2><form id="opportunity-form"><label>${t('Une proposition en une phrase','Your proposal in one sentence')}<input name="title" required maxlength="100"></label><label>${t('L’idée et la personne recherchée','The idea and who you are looking for')}<textarea name="description" required minlength="20" maxlength="500"></textarea></label><div class="form-grid"><label>${t('Premier format concret','A concrete first format')}<input name="format" required placeholder="${t('Une double page, une boucle de 30 s…','One spread, a 30-second loop…')}"></label><label>${t('Temps / disponibilité','Time / availability')}<input name="timing" required placeholder="${t('2 heures en novembre…','2 hours in November…')}"></label></div><label>${t('Conditions annoncées','Stated terms')}<textarea name="terms" required minlength="10" placeholder="${t('Budget ou échange créatif, crédit, droits à discuter…','Budget or creative exchange, credit, rights to discuss…')}"></textarea></label><label class="check"><input name="consent" type="checkbox" required><span>${t('Je souhaite rendre cette proposition publique après relecture. Aucun accord de collaboration n’est implicite.','I would like this proposal to be public after review. No collaboration agreement is implied.')}</span></label><button class="button">${t('Proposer · simulation','Submit · simulation')}</button></form>`);}
function openMessage(person,kind,opp=null,work=null){if(!requireMember())return;const c=creator(person);const pending=state.messages.some(m=>m.person===person&&m.kind===kind&&m.status==='pending');if(pending){notify(t('Une proposition est déjà en attente pour cette personne.','A proposal is already pending for this person.'));state.tab='messages';go('studio');return;}openDialog(`<h2 id="dialog-title">${kind==='feedback'?t('Un retour pour ','Feedback for '):t('Une idée pour ','An idea for ')}${esc(c.name)}.</h2><p>${kind==='feedback'?t('Un détail qui vous a marqué, une question, un regard concret. Pas un compliment obligé.','Something you noticed, a question, a useful perspective. Not a compulsory compliment.'):t('Commencez petit. Ce qui vous plaît, une idée réalisable et un premier pas.','Start small. What speaks to you, one feasible idea and a first step.')}</p><form id="message-form" data-person="${person}" data-kind="${kind}"><label>${t('Votre message','Your message')}<textarea name="text" required minlength="20" maxlength="2000" rows="4">${opp?esc(t('Votre proposition « ','Your proposal “')+tr(opp.title)+t(' » me parle. Je pourrais proposer…','” speaks to me. I could offer…')):work?esc(t('À propos de « ','About “')+tr(work.title)+t(' » : ','”: ')):''}</textarea></label>${kind==='collaboration'?`<div class="form-grid"><label>${t('Format / premier essai','Format / first experiment')}<input name="format" required value="${opp?esc(tr(opp.format)):''}"></label><label>${t('Temps / disponibilité','Time / availability')}<input name="timing" required placeholder="${t('Ce que je peux y consacrer','What I can realistically offer')}"></label></div>`:''}<label class="check"><input type="checkbox" required><span>${t('Je souhaite transmettre ce message. Mes coordonnées ne seront partagées qu’avec un accord mutuel.','I would like to send this message. Contact details will be shared only with mutual consent.')}</span></label><button class="button">${t('Simuler la demande','Simulate the request')}</button><p class="micro">${t('Le destinataire peut accepter, décliner ou ne pas répondre. Aucun email réel, aucun appel programmé.','The recipient can accept, decline or not reply. No real email and no call scheduled.')}</p></form>`);}
function receipt(){const c=state.candidate;openDialog(`<h2 id="dialog-title">${t('Nouvelle candidature','New application')}</h2><div class="receipt"><header>${t('À : équipe StrayDogs · adresse de démo','To: StrayDogs team · demo address')}<br>${t('Objet : candidature de ','Subject: application from ')}${esc(c.name)}<br><strong>${t('APERÇU UNIQUEMENT — NON ENVOYÉ','PREVIEW ONLY — NOT SENT')}</strong></header><div class="body"><p>${t('Une candidature attend votre examen.','An application is ready for review.')}</p><p><strong>${esc(c.name)}</strong><br>${esc(c.projectTitle)}</p><p>${t('Les coordonnées, l’audience et les pièces jointes sont consultables dans l’espace de revue privé. Rien n’est publié automatiquement.','Contact details, audience information and attachments are available in the private review area. Nothing is published automatically.')}</p><a href="#/moderation" class="button">${t('Examiner la candidature · démo','Review the application · demo')}</a></div></div>`);}
function candidateInput(el){if(!el.dataset.candidate)return;state.candidate[el.dataset.candidate]=el.type==='checkbox'?el.checked:el.value;}
function init(){
document.addEventListener('input',e=>{candidateInput(e.target);if(e.target.name==='interest')state.candidate.interests=[...document.querySelectorAll('input[name=interest]:checked')].map(x=>x.value);if(e.target.id==='creator-search'){state.search=e.target.value;const start=e.target.selectionStart;render();const el=$('#creator-search');el.focus();el.setSelectionRange(start,start);}});
document.addEventListener('change',e=>{candidateInput(e.target);if(e.target.name==='interest')state.candidate.interests=[...document.querySelectorAll('input[name=interest]:checked')].map(x=>x.value);if(e.target.id==='visual-file'){const f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>3*1024*1024){e.target.value='';notify(t('Choisissez une image PNG, JPG ou WebP de moins de 3 Mo.','Choose a PNG, JPG or WebP image under 3 MB.'));return;}const reader=new FileReader();reader.onload=()=>{state.candidate.visual=String(reader.result);render();notify(t('Visuel chargé en mémoire locale seulement.','Visual loaded into local memory only.'));};reader.onerror=()=>notify(t('Impossible de lire ce visuel. Aucun fichier transmis.','This visual could not be read. No file was sent.'));reader.readAsDataURL(f);}if(e.target.id==='attachment-file'){const f=e.target.files[0];if(!f)return;if(!['application/pdf','image/png','image/jpeg','image/webp'].includes(f.type)||f.size>10*1024*1024){e.target.value='';notify(t('Choisissez un PDF ou une image de moins de 10 Mo.','Choose a PDF or image under 10 MB.'));return;}state.candidate.attachment=f.name+' · '+t('référence locale, non transmise','local reference, not uploaded');render();notify(t('Nom de pièce jointe conservé pour la démo ; contenu non lu ni transmis.','Attachment name kept for the demo; contents not read or uploaded.'));}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;if(form.id==='application-form'){if(!form.reportValidity())return;const errors=Model.validateCandidate(state.candidate);if(errors.length){notify(t('Complétez les informations utiles, choisissez au moins un intérêt et vérifiez les liens.','Complete the key details, choose at least one interest and check your links.'));return;}notify('');go('preview');}else if(form.id==='work-form'){if(!form.reportValidity())return;const d=new FormData(form);if(!Model.queueWork({title:String(d.get('title')),url:String(d.get('url')),context:String(d.get('context')),need:String(d.get('need')),consent:d.has('consent'),socialPermission:d.has('socialPermission')})){notify(t('Vérifiez le titre, le contexte, le lien http/https et votre accord.','Check the title, context, http/https link and consent.'));return;}closeDialog();state.tab='works';notify(t('Proposition reçue dans la démo, en attente de relecture. Rien n’a été envoyé.','Submission received in the demo and awaiting review. Nothing was sent.'));go('studio');}else if(form.id==='opportunity-form'){if(!form.reportValidity())return;const d=new FormData(form);state.opportunities.push({id:'opp-'+state.next++,title:String(d.get('title')).trim(),description:String(d.get('description')).trim(),format:String(d.get('format')).trim(),timing:String(d.get('timing')).trim(),terms:String(d.get('terms')).trim(),status:'pending'});closeDialog();state.tab='works';notify(t('Appel à co-création proposé dans la démo, pas encore public.','Collaboration call submitted in the demo, not public yet.'));go('studio');}else if(form.id==='message-form'){if(!form.reportValidity())return;const d=new FormData(form);if(Model.request(form.dataset.person,form.dataset.kind,String(d.get('text')),String(d.get('format')||''),String(d.get('timing')||''))){closeDialog();state.tab='messages';notify(t('Demande simulée. Aucun message réel transmis.','Request simulated. No real message sent.'));go('studio');}}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
if(a==='close')closeDialog();
else if(a==='lang'){state.lang=b.dataset.lang;render();}
else if(a==='reset')openDialog(`<h2 id="dialog-title">${t('Repartir de zéro ?','Start over?')}</h2><p>${t('Les données fictives saisies dans cette page seront effacées. Aucun vrai compte n’est concerné.','Fictional details entered on this page will be cleared. No real account is affected.')}</p><div class="actions"><button class="button" data-action="confirm-reset">${t('Réinitialiser la démo','Reset the demo')}</button><button class="plain" data-action="close">${t('Annuler','Cancel')}</button></div>`);
else if(a==='confirm-reset'){Model.reset();notify('');closeDialog();go('home');render();}
else if(a==='filter'){state.filter=b.dataset.filter;render();}
else if(a==='clear-filter'){state.filter='all';state.search='';render();}
else if(a==='fill-demo'){state.candidate=demoCandidate();state.application='draft';render();notify(t('Exemple fictif rempli. Vérifiez ensuite l’aperçu public.','Fictional example filled in. Review the public preview next.'));}
else if(a==='demo-visual'){state.candidate.visual='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(portrait(2,'#edb399'));render();}
else if(a==='remove-visual'){state.candidate.visual='';render();}
else if(a==='remove-attachment'){state.candidate.attachment='';render();}
else if(a==='submit-application'){if(Model.submit()){notify(t('Candidature simulée : réception enregistrée dans cette page seulement.','Simulated application: receipt recorded only in this page.'));go('submitted');}}
else if(a==='moderate'){if(Model.moderate(b.dataset.decision)){notify(b.dataset.decision==='approve'?t('Validation simulée. Le choix de publication a été respecté.','Approval simulated. The publication choice has been respected.'):t('Ajustement demandé dans la démo. Aucun message envoyé.','Change requested in the demo. No message sent.'));render();}}
else if(a==='admin-receipt')receipt();
else if(a==='demo-login'){Model.demo();closeDialog();notify(t('Vous explorez l’espace d’Alex, membre fictif. Pas d’authentification réelle.','You are exploring Alex’s fictional member space. No real authentication.'));go('studio');}
else if(a==='tab'){state.tab=b.dataset.tab;render();}
else if(a==='open-submit-work')openWorkForm();
else if(a==='open-opportunity')openOpportunityForm();
else if(a==='message')openMessage(b.dataset.person,b.dataset.kind,null,works().find(w=>w.id===b.dataset.work));
else if(a==='external')openDialog(`<h2 id="dialog-title">${t('Chez le créateur','At the creator’s own space')}</h2><p>${t('Dans le site réel, ce bouton ouvrira le lien choisi par son auteur. Cette adresse est fictive et ne sera pas ouverte.','On the real site, this button will open the link chosen by its creator. This address is fictional and will not be opened.')}</p><div class="quote">${esc(b.dataset.url)}</div><button class="button light" data-action="close">${t('Revenir à la découverte','Back to exploring')}</button>`);
else if(a==='share'){const w=works().find(w=>w.id===b.dataset.id);if(!w)return;const c=w.creator==='alex'?(state.published||publicCopy(demoCandidate())):creator(w.creator);const text=state.shareDrafts[w.id]||t(`Je découvre « ${tr(w.title)} » de ${c.name}. Ce qui me parle : [ma raison personnelle].\n\nÀ découvrir ici : ${w.url}\nCrédit : ${c.name}`,`I have been exploring “${tr(w.title)}” by ${c.name}. What speaks to me: [my own reason].\n\nDiscover it here: ${w.url}\nCredit: ${c.name}`);openDialog(`<h2 id="dialog-title">${t('Avec vos mots.<br>Si vous en avez envie.','In your own words.<br>Only if you want to.')}</h2><label>${t('Votre recommandation','Your recommendation')}<textarea id="share-text" data-id="${w.id}" rows="7">${esc(text)}</textarea></label><div class="actions"><button class="button" data-action="save-share">${t('Garder mon brouillon','Keep my draft')}</button><button class="button light" data-action="select-share">${t('Sélectionner pour copier','Select to copy')}</button></div><p class="micro">${t('Aucun réseau connecté, aucune publication automatique. Le crédit et le lien original restent dans le texte.','No connected social account, no automated post. Credit and the original link stay in the text.')}</p>`);}
else if(a==='save-share'){const el=$('#share-text');state.shareDrafts[el.dataset.id]=el.value;closeDialog();notify(t('Brouillon gardé en mémoire de la démo. Rien n’a été publié.','Draft kept in demo memory. Nothing was posted.'));}
else if(a==='select-share'){$('#share-text').focus();$('#share-text').select();notify(t('Texte sélectionné : utilisez Copier. Aucun accès automatique au presse-papiers.','Text selected: use Copy. No automatic clipboard access.'));}
else if(a==='opportunity'){const o=DEMO_DATA.opportunities.find(o=>o.id===b.dataset.id);openDialog(`<h2 id="dialog-title">${esc(tr(o.title))}</h2><p>${esc(tr(o.description))}</p><div class="quote"><strong>${esc(tr(o.format))}</strong><br>${esc(tr(o.effort))}<br>${esc(tr(o.timing))}</div><p style="margin-top:18px">${esc(tr(o.terms))}</p><button class="button" data-action="respond-opportunity" data-id="${o.id}">${t('Proposer un premier pas','Suggest a first step')} ↗</button>`);}
else if(a==='respond-opportunity'){const o=DEMO_DATA.opportunities.find(o=>o.id===b.dataset.id);openMessage(o.creator,'collaboration',o);}
else if(a==='review-work'){const w=state.works.find(w=>w.id===b.dataset.id);openDialog(`<h2 id="dialog-title">${t('Relecture de la proposition','Review the submission')}</h2><h3>${esc(w.title)}</h3><p>${esc(w.context)}</p><p><strong>${t('Accord ronde publique : oui','Public round consent: yes')}</strong></p><p class="micro">${w.socialPermission?t('Une éventuelle reprise du visuel nécessite encore la validation du support et du crédit.','Any reuse of the visual still requires approval of the channel and credit.'):t('Aucune autorisation de reprise du visuel sur les réseaux.','No permission to reuse the visual on social channels.')}</p><div class="actions"><button class="button" data-action="approve-work" data-id="${w.id}">${t('Retenir dans la ronde · démo','Select for the round · demo')}</button><button class="plain" data-action="changes-work" data-id="${w.id}">${t('Demander un ajustement','Request a change')}</button></div>`);}
else if(a==='approve-work'||a==='changes-work'){Model.moderateWork(b.dataset.id,a==='approve-work'?'approve':'changes');closeDialog();render();notify(t('Décision appliquée à la démo uniquement.','Decision applied to the demo only.'));}
else if(a==='withdraw-work'){state.works=state.works.filter(w=>w.id!==b.dataset.id);render();notify(t('Proposition retirée, y compris de la ronde fictive.','Submission removed, including from the fictional round.'));}
else if(a==='publish-opportunity'){const o=state.opportunities.find(o=>o.id===b.dataset.id);if(o)o.status='published';render();notify(t('Proposition visible sur la page de co-création fictive.','Proposal visible on the fictional collaboration page.'));}
else if(a==='withdraw-opportunity'){state.opportunities=state.opportunities.filter(o=>o.id!==b.dataset.id);render();}
else if(a==='respond'){Model.respond(b.dataset.id,b.dataset.status);render();}
else if(a==='edit-profile'){if(state.demoSession)state.candidate=demoCandidate();state.application='draft';go('join');}
else if(a==='withdraw-profile'){Model.withdraw();render();notify(t('Fiche retirée du portfolio fictif. Votre espace membre reste accessible.','Profile removed from the fictional portfolio. Your member space remains accessible.'));}
else if(a==='privacy'){const c=state.demoSession?demoCandidate():state.candidate;openDialog(`<h2 id="dialog-title">${t('Vos données.<br>Vos choix.','Your details.<br>Your choices.')}</h2><div class="quote">${t('Email privé','Private email')}: ${esc(c.email)}\n${t('Canaux privés','Private channels')}: ${esc(c.audienceChannel)}\n${t('Audience privée','Private audience')}: ${esc(c.audience)}\n${t('Fiche publique','Public profile')}: ${state.published?t('oui','yes'):t('non','no')}</div><p>${t('Les visuels et pièces jointes de cette démo ne sont jamais transmis. Recharger la page efface les données.','Visuals and attachments in this demo are never uploaded. Reloading the page clears the data.')}</p><button class="button light" data-action="close">${t('Fermer','Close')}</button>`);}
else if(a==='leave')openDialog(`<h2 id="dialog-title">${t('Quitter cette démo ?','Leave this demo?')}</h2><p>${t('La fiche, les propositions et les échanges fictifs seront effacés.','The fictional profile, submissions and conversations will be cleared.')}</p><div class="actions"><button class="button" data-action="confirm-reset">${t('Effacer et quitter','Clear and leave')}</button><button class="plain" data-action="close">${t('Annuler','Cancel')}</button></div>`);
else if(a==='archive')openDialog(`<h2 id="dialog-title">${t('Une précédente ronde','A previous round')}</h2><p>${t('Archive de démonstration : les œuvres restent accessibles après leur mise en avant.','Demo archive: work remains accessible after its feature.')}</p>${DEMO_DATA.works.slice(Number(b.dataset.id),Number(b.dataset.id)+3).map(w=>`<div class="list-row"><div><h3>${esc(tr(w.title))}</h3><p>${esc(creator(w.creator).name)}</p></div><a href="#/work/${w.id}" class="link">${t('Découvrir','Explore')} ↗</a></div>`).join('')}`);
else if(a==='contact')openDialog(`<h2 id="dialog-title">${t('Une question ?','A question?')}</h2><p>${t('Pour contacter le collectif :','To contact the collective:')}</p><div class="quote">thomas@confluenceofminds.com</div><p>${t('Pour rejoindre la meute, utilisez le formulaire de candidature. Aucun email n’est envoyé depuis cette maquette.','To join the pack, use the application form. No email is sent from this prototype.')}</p><a href="#/join" class="button">${t('Ouvrir le formulaire','Open the application form')} ↗</a>`);
else if(a==='charter')openDialog(`<h2 id="dialog-title">${t('Indépendants.<br>Et attentifs aux autres.','Independent.<br>And mindful of each other.')}</h2><p>${t('Vous gardez vos droits, votre voix et votre rythme. Présentez des créations que vous êtes autorisé·e à partager ; créditez leurs auteurs.','Keep your rights, your voice and your own pace. Share work you have permission to present and credit its creators.')}</p><p>${t('Les retours, recommandations et collaborations sont libres. Aucun échange obligatoire de likes, aucune audience garantie.','Feedback, recommendations and collaborations are voluntary. No compulsory exchange of likes and no guaranteed audience.')}</p><p>${t('Avant de créer ensemble, clarifiez par écrit le temps, les usages, les crédits et tout budget éventuel.','Before making something together, agree in writing on time, usage, credits and any budget.')}</p>`);
else if(a==='report')openDialog(`<h2 id="dialog-title">${t('Signaler une fiche','Report a profile')}</h2><label>${t('Ce qui pose problème','What is the issue?')}<textarea id="report-text" rows="4"></textarea></label><button class="button" data-action="confirm-report">${t('Simuler le signalement','Simulate a report')}</button><p class="micro">${t('Aucun signalement réel n’est transmis.','No real report is sent.')}</p>`);
else if(a==='confirm-report'){closeDialog();notify(t('Signalement simulé uniquement.','Report simulated only.'));}
});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
render();
}
